  .clm-ap-summary-card { min-width: 100px; padding: 12px 14px; font-size: 13px; }
  .clm-summary-value { font-size: 16px; }
  .clm-ap-detail-section { padding: 16px; }
  .clm-ap-detail-section-title { font-size: 11px; margin-bottom: 12px; }
