  .clm-ap-header, .clm-ap-refreshed, .clm-ap-filters, .clm-ap-list, .clm-ap-detail, .clm-ap-done { padding-left: 16px; padding-right: 16px; }

  /* Math Card Stack for Tablet/Mobile */

  .clm-calc-dropdown { margin: 0 16px 24px; }
  .clm-calc-dropdown-body { padding: 16px; }

 }

@media (max-width: 480px) {
  .clm-ap-header { padding: 14px 16px; gap: 10px; align-items: flex-start; }
