  .clm-ap-card { padding: 16px; }
  .clm-ap-card-top { flex-direction: column; gap: 6px; }
  .clm-ap-card-num { font-size: 11px; }
  .clm-ap-card-name { font-size: 14px; }
  .clm-ap-card-right { width: 100%; justify-content: flex-start; }
  .clm-badge { padding: 2px 6px; font-size: 10px; }
  .clm-ap-card-metrics { gap: 16px; font-size: 12px; }
  .clm-ap-metric-label { font-size: 10px; }
  .clm-ap-metric-value { font-size: 13px; }
  .clm-ap-card-footer { flex-direction: column; gap: 8px; font-size: 11px; }
  .clm-ap-footer-cta { margin-left: 0; }
  .clm-ap-detail-header { padding: 12px 14px; gap: 8px; flex-wrap: wrap; }
  .clm-back-btn { padding: 5px 10px; font-size: 12px; order: -1; flex-shrink: 0; }
  .clm-ap-detail-title { font-size: 13px; width: 100%; order: 1; }
  .clm-ap-summary-row { border-bottom: none; }
  .clm-ap-summary-card { flex: 0 0 calc(50% - 1px); min-width: unset; padding: 10px 12px; border-right: none; border-bottom: 1px solid #e0e6ed; }
  .clm-ap-summary-card:nth-child(odd) { border-right: 1px solid #e0e6ed; }
  .clm-ap-summary-card:nth-child(2n + 3) { border-bottom: 1px solid #e0e6ed; }
  .clm-summary-label { font-size: 10px; margin-bottom: 4px; }
