  .clm-ap-input, .clm-ap-textarea { font-size: 13px; padding: 8px 10px; }
  .clm-ap-textarea { min-height: 60px; }
.clm-ap-decision-actions { grid-template-columns: 1fr; gap: 10px; }
  .clm-rfi-history-header { flex-direction: column; align-items: flex-start; gap: 6px; }
  .clm-ap-done { padding: 40px 20px; }
  .clm-ap-done-icon { width: 50px; height: 50px; font-size: 24px; margin-bottom: 16px; }
