/* ============================================================
   APPROVER DETAIL REDESIGN (append-only)
   ============================================================ */
.clm-ap-page { padding: 24px 28px 32px; background: #F9FAFB; }
.clm-ap-sec { margin-bottom: 28px; }
.clm-ap-sec-title { display:flex; align-items:center; gap:12px; font-size:13px; font-weight:700; text-transform:uppercase; letter-spacing:1px; color:#1a1a1a; margin-bottom:14px; }
.clm-ap-sec-num { width:24px; height:24px; border-radius:50%; background:#F3D54E; color:#1a1a1a; font-size:12px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }

/* Generic data tables */
.clm-ap-table-wrap { overflow-x:auto; border:1px solid #e0e6ed; border-radius:8px; background:#fff; box-shadow:0 2px 8px rgba(0,0,0,0.03); }
.clm-ap-table { width:100%; border-collapse:collapse; font-size:13px; }
.clm-ap-table th { background:#1a1a1a; color:#F3D54E; padding:12px 14px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.5px; text-align:left; line-height:1.3; }
.clm-ap-table td { padding:14px; color:#1a1a1a; border-top:1px solid #f0f4f8; vertical-align:middle; }
.clm-ap-table td.strong, .clm-ap-table .strong { font-weight:700; }
.clm-ap-table-nowrap th, .clm-ap-table-nowrap td { white-space:nowrap; text-align:center; }
.clm-ap-table-nowrap th:first-child, .clm-ap-table-nowrap td:first-child { text-align:left; }
.clm-ap-table .pan-cell { background:#fcfcfc; }

/* Super-header row (group labels) */
.clm-ap-table tr.super th { font-size:11px; letter-spacing:1px; text-align:center; border-bottom:none; color:#1a1a1a; }
.clm-ap-table tr.super th.bg-blank { background:#f8f9fa; }
.clm-ap-table tr.super th.bg-code { background:#e6f0fa; color:#0b5394; }
.clm-ap-table tr.super th.bg-pan  { background:#fdf5e6; color:#b45f06; }
.clm-ap-table tr.super th.bg-req  { background:#e8f5e9; color:#2e7d32; }
.clm-ap-table tr.super th.bg-assess { background:#f0eafa; color:#6a3fb5; }

.clm-ap-table td.implied-dev { background:#fef5f4; }
.clm-ap-dev-flag { font-size:10px; font-weight:700; color:#E23D28; margin-top:4px; letter-spacing:0.5px; }
.clm-ap-note { margin-top:10px; font-size:12px; color:#5a6a7a; background:#fffcf0; border:1px solid #f9e79f; border-radius:6px; padding:8px 12px; display:inline-block; }
.clm-ap-summary-boxed { border:1px solid #e0e6ed; border-radius:8px; overflow:hidden; }

/* Two-column body */
.clm-ap-grid { display:grid; grid-template-columns:minmax(0,1.1fr) minmax(0,1fr); gap:24px; align-items:start; }
.clm-ap-grid.single { grid-template-columns:minmax(0,1fr); }
.clm-ap-col-left { background:#f5f5f3; border:1px solid #e0e6ed; border-radius:8px; padding:20px; }
.clm-ap-col-right { min-width:0; }
.clm-ap-rsec { margin-bottom:26px; }
.clm-ap-rsec .clm-ap-detail-section-title { margin-bottom:12px; }
.clm-ap-col-right .clm-aging-table { min-width:640px; font-size:12px; margin-top:0; }
.clm-ap-col-right .clm-aging-table th { padding:8px 10px; font-size:10px; }
.clm-ap-col-right .clm-aging-table td { padding:8px 10px; }
.clm-ap-scroll { max-height:320px; overflow-y:auto; padding-right:4px; }
.clm-ap-decision-section { background:#fff; border:1px solid #e0e6ed; border-radius:8px; padding:20px; }

/* Documents */
.clm-ap-doc-row { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:10px 14px; background:#fff; border:1px solid #e0e6ed; border-radius:6px; margin-bottom:8px; }
.clm-ap-doc-name { font-size:13px; color:#1a1a1a; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.clm-ap-doc-actions { display:flex; align-items:center; gap:12px; flex-shrink:0; }
.clm-ap-doc-link { font-size:12px; font-weight:700; color:#1782c5; text-decoration:none; }
.clm-ap-doc-link:hover { text-decoration:underline; }

/* Tool working */
.clm-tw-heading { font-size:16px; font-weight:700; color:#1a1a1a; margin-bottom:16px; }
.clm-tw-card { background:#fff; border:1px solid #e0e6ed; border-top:3px solid #F3D54E; border-radius:6px; margin-bottom:12px; overflow:hidden; }
.clm-tw-card-title { padding:12px 16px; font-size:12px; font-weight:700; color:#1a1a1a; border-bottom:1px solid #f0f4f8; }
.clm-tw-subnote { padding:8px 16px; font-size:11px; color:#7f8c9a; }
.clm-tw-kv { width:100%; border-collapse:collapse; font-size:13px; }
.clm-tw-kv th { width:45%; text-align:left; padding:11px 16px; color:#1a1a1a; font-weight:600; border-top:1px solid #f0f4f8; }
.clm-tw-kv td { padding:11px 16px; color:#5a6a7a; border-top:1px solid #f0f4f8; }
.clm-tw-kv td.strong { color:#1a1a1a; font-weight:700; }
.clm-tw-matrix { width:100%; border-collapse:collapse; font-size:12px; }
.clm-tw-matrix th { text-align:left; padding:10px 14px; font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.5px; color:#5a6a7a; background:#f9fafb; border-bottom:1px solid #e0e6ed; }
.clm-tw-matrix td { padding:9px 14px; border-bottom:1px solid #f0f4f8; color:#5a6a7a; }
.clm-tw-matrix td.strong { color:#1a1a1a; font-weight:700; }
.clm-tw-matrix .num { text-align:right; }
.clm-tw-matrix .muted { color:#b8c2cc; }
.clm-tw-total td { background:#fcf1de; color:#1a1a1a !important; font-weight:700; border-top:2px solid #e0e6ed; }
.clm-tw-tag { display:inline-block; margin-left:6px; padding:1px 6px; border-radius:4px; font-size:9px; font-weight:700; text-transform:uppercase; }
.clm-tw-tag-ai  { background:#eef6fb; color:#1782c5; border:1px solid #1782c5; }
.clm-tw-tag-ovr { background:#fffbeb; color:#b58105; border:1px solid #ffc107; }
.clm-tw-ratings { display:flex; gap:12px; padding:14px 16px 4px; flex-wrap:wrap; }
.clm-tw-rating { flex:1; min-width:150px; text-align:center; padding:14px; border:1px solid #e0e6ed; border-radius:6px; background:#fff; }
.clm-tw-rating-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.5px; color:#7f8c9a; margin-bottom:6px; }
.clm-tw-rating-value { font-size:28px; font-weight:700; color:#1a1a1a; }
.clm-tw-result { text-align:center; padding:14px 16px; margin-bottom:12px; background:#fffcf0; border:1px solid #F3D54E; border-radius:6px; }
.clm-tw-result-label { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.8px; color:#b58105; margin-bottom:6px; }
.clm-tw-result-value { font-size:24px; font-weight:700; color:#1a1a1a; }
.clm-tw-result-sub { font-size:11px; color:#7f8c9a; margin-top:4px; }
.clm-tw-result.clm-tw-safe { background:#eafaf1; border:1px solid #27ae60; }
.clm-tw-safe .clm-tw-result-label, .clm-tw-safe .clm-tw-result-value { color:#1e8449; }

@media (max-width: 1100px) {
  .clm-ap-grid { grid-template-columns:minmax(0,1fr); }
}
@media (max-width: 768px) {
  .clm-ap-page { padding:16px 12px 24px; }
  .clm-ap-col-left { padding:12px; }
}
/* ============================================================
   PDF EXPORT OVERRIDES (class is added to the live element only
   while the PDF is being captured; JS sets the width)
   ============================================================ */
.pdf-export-mode {
    background: #ffffff !important;
    min-width: 1400px !important;
    max-width: none !important;
    margin: 0 !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
}

/* Un-clip every scroll area, including the inline overflow-x wrappers (ageing table etc.) */
.pdf-export-mode .clm-ap-table-wrap,
.pdf-export-mode .tracker-scroll-wrap,
.pdf-export-mode .clm-ap-scroll,
.pdf-export-mode .clm-matrix-table-container,
.pdf-export-mode .clm-ap-col-left,
.pdf-export-mode .clm-ap-col-right,
.pdf-export-mode [style*="overflow-x"] {
    overflow: visible !important;
    max-height: none !important;
}

/* Keep the same two-column layout as the widget, whatever the screen width */
.pdf-export-mode .clm-ap-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) !important;
}
.pdf-export-mode .clm-ap-grid.single {
    grid-template-columns: minmax(0, 1fr) !important;
}

/* Hide interactive-only UI */
.pdf-export-mode .clm-ap-detail-header button,
.pdf-export-mode .clm-back-btn,
.pdf-export-mode .clm-ap-decision-section,
.pdf-export-mode .clm-ap-doc-actions {
    display: none !important;
}

sp_widget.script:
(function() {

    var action = input && input.action;

    // NEW ─ safe numeric read from a record field
    function grNum(rec, field) { return parseFloat(rec.getValue(field)) || 0; }

    function buildApprovalSteps(gr) {

        var segmentRaw = (gr.segment + '').toLowerCase().trim();
        var segment    = segmentRaw.split('|')[0].trim();

        var targetApprover = (gr.getValue('required_approver_level') || '').trim();

        // ── cement_bpd detection ─────────────────────────────────
        // Primary: read flag. Fallback: TSH_BPD + RHM both populated = cement_bpd
        var isCementBpd = (gr.getValue('cement_bpd') + '') === 'true';
        if (!isCementBpd && segment === 'bpd') {
            var hasTshBpd = (gr.getValue('u_approver_tsh_bpd') || '').trim() !== '';
            var hasRhm    = (gr.getValue('u_approver_rhm')     || '').trim() !== '';
            if (hasTshBpd && hasRhm) isCementBpd = true;
        }

        // ── ZCH + HO visibility rule ─────────────────────────────
        // Only shown when target approver is CCH and above.
        var cementCCHAndAbove    = ['NSH_CCH', 'CMO', 'CMO_CFO', 'MD'];
        var rmcCCHAndAbove       = ['HEAD_KEY_CCH', 'BH', 'BH_CFO', 'MD'];
        var bpdCCHAndAbove       = ['CCH_HBPD', 'BH', 'CFO', 'MD'];
        var cementBpdCCHAndAbove = ['NSH_CCH', 'CMO', 'CMO_CFO', 'MD'];

        var showZchHo = false;
        if      (segment === 'rmc')                    showZchHo = rmcCCHAndAbove.indexOf(targetApprover)       !== -1;
        else if (segment === 'bpd' && isCementBpd)    showZchHo = cementBpdCCHAndAbove.indexOf(targetApprover) !== -1;
        else if (segment === 'bpd')                    showZchHo = bpdCCHAndAbove.indexOf(targetApprover)       !== -1;
        else                                           showZchHo = cementCCHAndAbove.indexOf(targetApprover)    !== -1;

        // ── Build chains dynamically ─────────────────────────────
        var CEMENT_CHAIN = [
            { label: 'TSH', field: 'u_approver_tsh' },
            { label: 'RHM', field: 'u_approver_rhm' }
        ];
        if (showZchHo) {
            CEMENT_CHAIN.push({ label: 'ZCH', field: 'u_approver_zch' });
        }
        CEMENT_CHAIN.push({ label: 'ZHM', field: 'u_approver_zhm' });
        if (showZchHo) {
            CEMENT_CHAIN.push({ label: 'HO', field: 'u_approver_ho' });
        }
        CEMENT_CHAIN = CEMENT_CHAIN.concat([
            { label: 'NSH', field: 'u_approver_nsh'     },
            { label: 'CCH', field: 'u_approver_nsh_cch' },
            { label: 'CMO', field: 'u_approver_cmo'     },
            { label: 'CFO', field: 'u_approver_cmo_cfo' },
            { label: 'MD',  field: 'u_approver_md'      }
        ]);

        var RMC_CHAIN = [
            { label: 'TSM',            field: 'u_approver_tsm'             },
            { label: 'RH CH RMC',      field: 'u_approver_rh_ch_rmc'       },
            { label: 'ZH RMC',         field: 'u_approver_zh_rmc'          },
            { label: 'HEAD RMC',       field: 'u_approver_head_rmc'        },
            { label: 'HEAD KEY & RMC', field: 'u_approver_head_key_ch_rmc' }
        ];
        if (showZchHo) {
            RMC_CHAIN.push({ label: 'ZCH', field: 'u_approver_zch' });
            RMC_CHAIN.push({ label: 'HO',  field: 'u_approver_ho'  });
        }
        RMC_CHAIN = RMC_CHAIN.concat([
            { label: 'CCH', field: 'u_approver_head_key_cch' },
            { label: 'BH',  field: 'u_approver_bh'           },
            { label: 'CFO', field: 'u_approver_bh_cfo'       },
            { label: 'MD',  field: 'u_approver_md'           }
        ]);

        var BPD_CHAIN = [
            { label: 'TSH BPD', field: 'u_approver_tsh_bpd' },
            { label: 'ZH BPD',  field: 'u_approver_zh_bpd'  },
            { label: 'HSBPD',   field: 'u_approver_hsbpd'   },
            { label: 'HBPD',    field: 'u_approver_hbpd'    }
        ];
        if (showZchHo) {
            BPD_CHAIN.push({ label: 'ZCH', field: 'u_approver_zch' });
            BPD_CHAIN.push({ label: 'HO',  field: 'u_approver_ho'  });
        }
        BPD_CHAIN = BPD_CHAIN.concat([
            { label: 'CCH', field: 'u_approver_cch_hbpd' },
            { label: 'BH',  field: 'u_approver_bh'       },
            { label: 'CFO', field: 'u_approver_cfo'      },
            { label: 'MD',  field: 'u_approver_md'       }
        ]);

        // ── CEMENT+BPD hybrid chain ──────────────────────────────
        var CEMENT_BPD_CHAIN = [
            { label: 'TSH BPD',    field: 'u_approver_tsh_bpd' },
            { label: 'ZH BPD',     field: 'u_approver_zh_bpd'  },
            { label: 'RHM Cement', field: 'u_approver_rhm'      },
            { label: 'ZHM Cement', field: 'u_approver_zhm'      }
        ];
        if (showZchHo) {
            CEMENT_BPD_CHAIN.push({ label: 'ZCH', field: 'u_approver_zch' });
            CEMENT_BPD_CHAIN.push({ label: 'HO',  field: 'u_approver_ho'  });
        }
        CEMENT_BPD_CHAIN = CEMENT_BPD_CHAIN.concat([
            { label: 'NSH', field: 'u_approver_nsh'     },
            { label: 'CCH', field: 'u_approver_nsh_cch' },
            { label: 'CMO', field: 'u_approver_cmo'     },
            { label: 'CFO', field: 'u_approver_cmo_cfo' },
            { label: 'MD',  field: 'u_approver_md'      }
        ]);

        var chain = (segment === 'rmc')                ? RMC_CHAIN
                  : (segment === 'bpd' && isCementBpd) ? CEMENT_BPD_CHAIN
                  : (segment === 'bpd')                 ? BPD_CHAIN
                  : CEMENT_CHAIN;

        var mapBySysId = {};
        var saGR = new GlideRecord('sysapproval_approver');
        var saQuery = saGR.addQuery('sysapproval', gr.sys_id);
        saQuery.addOrCondition('document_id', gr.sys_id);
        saGR.addQuery('state', '!=', 'cancelled');

        var lastSubmitted = gr.getValue('u_last_submitted_on');
        if (lastSubmitted) {
            saGR.addQuery('sys_created_on', '>=', lastSubmitted);
        }

        saGR.orderByDesc('sys_created_on');
        saGR.query();

        var commentsByApprover = {};
        while (saGR.next()) {
            var approverId = saGR.getValue('approver') + '';
            var state = (saGR.getValue('state') + '').toLowerCase();

            if (state == 'approved')
                mapBySysId[approverId] = 'approved';
            else if (state == 'rejected')
                mapBySysId[approverId] = 'rejected';
            else
                mapBySysId[approverId] = 'pending';

            var jf = new GlideRecord('sys_journal_field');
            jf.addQuery('element_id', saGR.sys_id);
            jf.orderByDesc('sys_created_on');
            jf.query();

            if (jf.next()) {
                commentsByApprover[approverId] = jf.value + '';
            }
        }

        var steps = [];
        steps.push({ label: 'Submitted', state: 'approved' });
        for (var i = 0; i < chain.length; i++) {
            var entry = chain[i];
            var approverId = gr.getValue(entry.field);
            if (!approverId) continue;

            var approverName = '';
            try { approverName = gr[entry.field].getDisplayValue() + ''; } catch(e) {}
            var stepComment = commentsByApprover[approverId] || '';
            steps.push({
                label: entry.label,
                state: mapBySysId[approverId] || 'pending',
                approver_name: approverName,
                approver_sys_id: approverId,
                comment: stepComment,
                // BR "CLM Auto Approval" writes this exact comment text —
                // used to exclude auto-approved steps from RFI targeting.
                auto_approved: stepComment.indexOf('Auto Approved by') === 0
            });
        }

        steps.push({
            label: 'Completed',
            state: (gr.state + '') == 'Approved' ? 'approved' : 'pending'
        });

        return steps;
    }

    function loadRequests() {
        var results = [];
        var currentUser = gs.getUserID();

        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        gr.addQuery('state', 'Submitted');
        gr.orderByDesc('sys_created_on');
        gr.query();

        while (gr.next()) {
            var isMyTurn = false;
            var myApproval = new GlideRecord('sysapproval_approver');
            myApproval.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
            myApproval.addQuery('document_id', gr.sys_id + '');
            myApproval.addQuery('approver', currentUser);
            myApproval.addQuery('state', 'requested');
            myApproval.query();

            if (myApproval.next()) {
                isMyTurn = true;
            }

            if (!isMyTurn) continue;

            var custSysId  = gr.customer + '';
            var custName   = '';
            var custCode   = '';
            var custPAN    = '';
            var panLevelSD = 0;

            var custDepot = '', custDepotName = '', custZone = '', custZoneName = '', custRegion = '', custRegionName = '';
            var cGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
            if (custSysId && cGr.get(custSysId)) {
                custName       = cGr.customer_name     + '';
                custCode       = cGr.customer_code_sap + '';
                custPAN        = cGr.pan               + '';
                custDepot      = cGr.depot             + '';
                custDepotName  = cGr.depot_name         + '';
                custZone       = cGr.zone              + '';
                custZoneName   = cGr.zone_name          + '';
                custRegion     = cGr.region             + '';
                custRegionName = cGr.region_name        + '';
            } else {
                custName = gr.customer.getDisplayValue() || 'Unknown';
                custCode = 'N/A';
            }

            if (custPAN) {
                var panGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
                panGr.addQuery('pan', custPAN);
                panGr.query();
                while (panGr.next()) {
                    panLevelSD += parseFloat(panGr.current_sd_amount) || 0;
                }
            }

            var initiatorName = '';
            var iGr = new GlideRecord('sys_user');
            if (iGr.get(gr.initiator + '')) initiatorName = iGr.name + '';
            if (!initiatorName) initiatorName = gr.initiator.getDisplayValue() || 'Unknown';

            var total = 0, safe = 0, warning = 0, critical = 0, toxic = 0;
            var agGr = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agGr.addQuery('customer', custSysId);
            agGr.orderByDesc('snapshot_month');
            agGr.setLimit(6);
            agGr.query();

            while (agGr.next()) {
                total    += parseFloat(agGr.total_outstanding)   || 0;
                safe     += (parseFloat(agGr.bucket_0_30_days)   || 0)
                          + (parseFloat(agGr.bucket_22_30_days)  || 0)
                          + (parseFloat(agGr.bucket_31_45_days)  || 0)
                          + (parseFloat(agGr.bucket_46_60_days)  || 0);
                warning  += parseFloat(agGr.bucket_61_75_days)   || 0;
                critical += parseFloat(agGr.bucket_76_90_days)   || 0;
                toxic    += (parseFloat(agGr.bucket_91_120_days) || 0)
                          + (parseFloat(agGr.bucket_gt120_days)  || 0);
            }

            var agingTable = [];
            var agGr2 = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agGr2.addQuery('customer', custSysId);
            agGr2.orderByDesc('snapshot_month');
            agGr2.setLimit(6);
            agGr2.query();

            while (agGr2.next()) {
                agingTable.push({
                    month:   agGr2.snapshot_month.getDisplayValue(),
                    b0_30:   parseFloat(agGr2.bucket_0_30_days)   || 0,
                    b22_30:  parseFloat(agGr2.bucket_22_30_days)  || 0,
                    b31_45:  parseFloat(agGr2.bucket_31_45_days)  || 0,
                    b46_60:  parseFloat(agGr2.bucket_46_60_days)  || 0,
                    b61_75:  parseFloat(agGr2.bucket_61_75_days)  || 0,
                    b76_90:  parseFloat(agGr2.bucket_76_90_days)  || 0,
                    b91_120: parseFloat(agGr2.bucket_91_120_days) || 0,
                    b120:    parseFloat(agGr2.bucket_gt120_days)  || 0,
                    total:   parseFloat(agGr2.total_outstanding)  || 0
                });
            }

            var rowCount = agingTable.length;
            if (rowCount > 0) {
                var avg0_30 = 0, avg22_30 = 0, avg31_45 = 0, avg46_60 = 0, avg61_75 = 0, avg76_90 = 0, avg91_120 = 0, avg120 = 0, avgTotal = 0;
                agingTable.forEach(function(r) {
                    avg0_30 += r.b0_30;
                    avg22_30 += r.b22_30;
                    avg31_45 += r.b31_45; avg46_60 += r.b46_60; avg61_75 += r.b61_75;
                    avg76_90 += r.b76_90; avg91_120 += r.b91_120; avg120 += r.b120; avgTotal += r.total;
                });
                agingTable.push({
                    month: 'Average',
                    b0_30: avg0_30 / rowCount,
                    b22_30: avg22_30 / rowCount,
                    b31_45: avg31_45 / rowCount, b46_60: avg46_60 / rowCount,
                    b61_75: avg61_75 / rowCount, b76_90: avg76_90 / rowCount, b91_120: avg91_120 / rowCount,
                    b120: avg120 / rowCount, total: avgTotal / rowCount, isAverage: true
                });
            }

            var agingDetail = null;
            if (total > 0) {
                agingDetail = {
                    safe_pct:  Math.round((safe     / total) * 100),
                    warn_pct:  Math.round((warning  / total) * 100),
                    crit_pct:  Math.round((critical / total) * 100),
                    toxic_pct: Math.round((toxic    / total) * 100)
                };
            }

            var reviewDateStr = '';
            try { reviewDateStr = gr.next_review_date.getDisplayValue() || ''; } catch(e) {}

            var sequence = [];
            try { sequence = JSON.parse(gr.u_approver_sequence + ''); } catch(e) { sequence = []; }

            var codeLevelCurrentEarly = parseFloat(gr.getValue('u_code_level_current_limit')) || 0;
            var codeLevelTotalEarly   = parseFloat(gr.getValue('u_code_level_total_requested')) || 0;

            var previousApproval = null;
            var pa = new GlideRecord('sysapproval_approver');
            pa.addQuery('document_id', gr.sys_id + '');
            pa.addQuery('state', 'approved');
            pa.orderByDesc('sys_updated_on');
            pa.setLimit(1);
            pa.query();

            if (pa.next()) {
                var prevAmount = 0;
                if ((gr.customer_type + '') === 'Trade') {
                    // Code-level is the real decision surface for Trade.
                    // Fall back to legacy approved_limit for older records
                    // that only ever stored the PAN-level figure.
                    prevAmount = parseFloat(gr.getValue('u_approved_code_limit')) || parseFloat(gr.approved_limit) || 0;
                } else {
                    prevAmount = parseFloat(gr.approved_limit) || 0;
                }
                previousApproval = {
                    approver: pa.approver.getDisplayValue(),
                    amount:   prevAmount
                };
            }

            var approvalComments = [];
            var apprGR = new GlideRecord('sysapproval_approver');
            apprGR.addQuery('document_id', gr.sys_id);
            apprGR.addQuery('state', 'IN', 'approved,rejected,cancelled');
            apprGR.orderByDesc('sys_created_on');
            apprGR.query();

            while (apprGR.next()) {
                var commentText = '';
                var jf = new GlideRecord('sys_journal_field');
                jf.addQuery('element_id', apprGR.sys_id);
                jf.orderByDesc('sys_created_on');
                jf.query();
                if (jf.next()) commentText = jf.value + '';
                if (!commentText) continue;

                approvalComments.push({
                    approver: apprGR.approver.getDisplayValue() + '',
                    state: apprGR.state + '',
                    comments: commentText,
                    updated_on: apprGR.getDisplayValue('sys_updated_on')
                });
            }

            var attachments = [];
            // 1. Request Attachments
            var attGR = new GlideRecord('sys_attachment');
            attGR.addQuery('table_name', 'x_birl3_clm_clm_new_credit_request');
            attGR.addQuery('table_sys_id', gr.getUniqueValue());
            attGR.query();
            while (attGR.next()) {
                attachments.push({
                    sys_id: attGR.getUniqueValue(),
                    file_name: attGR.getValue('file_name')
                });
            }

            // 2. RFI History & Attachment Roll-up (Visible to ALL approvers)
            var rfiSysIds = [];
            var answeredRfisForThisRequest = [];
            var allRfis = new GlideRecord('x_birl3_clm_clm_rfi');
            allRfis.addQuery('u_request', gr.getUniqueValue());
            allRfis.orderByDesc('sys_updated_on');
            allRfis.query();

            while (allRfis.next()) {
                rfiSysIds.push(allRfis.getUniqueValue());

                if (allRfis.getValue('u_status') === 'answered') {
                    answeredRfisForThisRequest.push({
                        target_role: allRfis.getValue('u_target_role'),
                        target_name: allRfis.getDisplayValue('u_target_user') + '',
                        question: allRfis.getValue('u_question'),
                        response: allRfis.getValue('u_response'),
                        responded_on: allRfis.getDisplayValue('u_responded_on') || allRfis.getDisplayValue('sys_updated_on'),
                        raised_by_name: allRfis.u_raised_by.getDisplayValue() + ' (' + allRfis.getValue('u_raised_by_role') + ')'
                    });
                }
            }

            // Bring RFI attachments into the main attachment list
            if (rfiSysIds.length > 0) {
                var rfiAttGr = new GlideRecord('sys_attachment');
                rfiAttGr.addQuery('table_name', 'x_birl3_clm_clm_rfi');
                rfiAttGr.addQuery('table_sys_id', 'IN', rfiSysIds.toString());
                rfiAttGr.query();
                while (rfiAttGr.next()) {
                    attachments.push({
                        sys_id: rfiAttGr.getUniqueValue(),
                        file_name: '[RFI] ' + rfiAttGr.getValue('file_name')
                    });
                }
            }

            // TOOL WORKING PARSING (TRADE)
            var toolMatrix = {};
            try { toolMatrix = JSON.parse(gr.getValue('u_tool_matrix_json') || '{}'); } catch(e) {}

            var tradeParamDefs = [
                { name: "Age of Company", weight: 5, options: [{label:"Best (> 15 Yrs)",score:10},{label:"Good (> 10 Yrs)",score:7},{label:"Average (> 5 Yrs)",score:5},{label:"Poor (< 5 Yrs)",score:2}] },
                { name: "Cement/RMC Potential", weight: 10, options: [{label:"Best (> 25,000 MT)",score:10},{label:"Good (10k-25k MT)",score:7},{label:"Average (3k-10k MT)",score:5},{label:"Poor (< 3,000 MT)",score:2}] },
                { name: "Current Share (in %)", weight: 10, options: [{label:"Best (> 70)",score:10},{label:"Good (50-70)",score:7},{label:"Average (30-50)",score:5},{label:"Poor (< 30)",score:2}] },
                { name: "Corporate Body", weight: 5, options: [{label:"Listed",score:10},{label:"Unlisted Ltd",score:7},{label:"Partnership Firm",score:5},{label:"Proprietor",score:2}] },
                { name: "Mgmt. Competence", weight: 5, options: [{label:"Excellent",score:10},{label:"V. Good",score:7},{label:"Good",score:5},{label:"Average",score:2}] },
                { name: "Revenue", weight: 5, options: [{label:"Best (> 100 CR)",score:10},{label:"Good (50-100 CR)",score:7},{label:"Average (10-50 CR)",score:5},{label:"Poor (< 10 CR)",score:2}] },
                { name: "Sales Growth% (CAGR)", weight: 10, options: [{label:"Best (> 20%)",score:10},{label:"Good (10-20%)",score:7},{label:"Average (5-10%)",score:5},{label:"Poor (< 5%)",score:2}] },
                { name: "Gross Profit%", weight: 5, options: [{label:"Best (> 20%)",score:10},{label:"Good (10-20%)",score:7},{label:"Average (5-10%)",score:5},{label:"Poor (< 5%)",score:2}] },
                { name: "EBITDA%", weight: 10, options: [{label:"Best (> 15%)",score:10},{label:"Good (10-15%)",score:7},{label:"Average (5-10%)",score:5},{label:"Poor (< 5%)",score:2}] },
                { name: "Net WCC Days", weight: 5, options: [{label:"Best (< 30)",score:10},{label:"Good (30-60)",score:7},{label:"Average (60-90)",score:5},{label:"Poor (> 90)",score:2}] },
                { name: "A/R Days", weight: 15, options: [{label:"Best (< 30)",score:10},{label:"Good (30-60)",score:7},{label:"Average (60-90)",score:5},{label:"Poor (> 90)",score:2}] },
                { name: "Inventory Days", weight: 5, options: [{label:"Best (< 30)",score:10},{label:"Good (30-60)",score:7},{label:"Average (60-90)",score:5},{label:"Poor (> 90)",score:2}] },
                { name: "A/P Days", weight: 10, options: [{label:"Best (75-120)",score:10},{label:"Good (45-75)",score:7},{label:"Average (15-45)",score:5},{label:"Poor (< 15 or > 120)",score:2}] }
            ];

            var toolMatrixList = [];
            for (var pi = 0; pi < tradeParamDefs.length; pi++) {
                var def = tradeParamDefs[pi];
                var saved = toolMatrix[def.name] || null;
                var matchedScore = 0;
                var matchedLabel = '—';

                if (saved && saved.label) {
                    matchedLabel = saved.label;
                    var cleanSavedLabel = (saved.label + '').toLowerCase().split('(score')[0].trim();
                    for (var oi = 0; oi < def.options.length; oi++) {
                        var opt = def.options[oi];
                        var cleanOptLabel = opt.label.toLowerCase().split('(score')[0].trim();

                        // Exact match only — substring match would let
                        // "Unlisted" accidentally match "Listed"
                        if (cleanSavedLabel === cleanOptLabel) {
                            matchedScore = opt.score;
                            break;
                        }
                    }
                }
                var weightedValue = (matchedScore * def.weight) / 10;
                toolMatrixList.push({
                    name: def.name,
                    label: matchedLabel,
                    score: matchedScore,
                    weight: def.weight,
                    weighted_value: weightedValue.toFixed(1),
                    overridden: saved ? !!saved.overridden : false,
                    mappingType: saved ? saved.mappingType : 'Manual'
                });
            }

            var codeLevelCurrent = codeLevelCurrentEarly;
            var codeLevelTotal   = codeLevelTotalEarly;
            var codeLevelRequestedAdditional = parseFloat(gr.getValue('u_requested_additional_limit')) || 0;

            var p1Value = gr.getValue('u_tool_p1');
            var parsedP1 = (p1Value !== null && p1Value !== '') ? parseFloat(p1Value) : null;

            // ── RFI: eligible targets + any currently-open RFI ──────────
            var approvalStepsForThisRequest = buildApprovalSteps(gr);

            var seenSysIds = {};
            var rfiTargetsForThisRequest = [];

            // 1. Add all approved users, tracking their sys_ids to prevent duplicates
            approvalStepsForThisRequest.forEach(function(s) {
                if (s.state === 'approved' && s.approver_sys_id && !seenSysIds[s.approver_sys_id]) {
                    seenSysIds[s.approver_sys_id] = true;
                    rfiTargetsForThisRequest.push({
                        sys_id: s.approver_sys_id,
                        label: s.label,
                        name: s.approver_name
                    });
                }
            });

            // 2. Add the Initiator ONLY if they aren't already in the list (e.g., as TSH)
            var currentInitiator = gr.getValue('initiator');
            if (currentInitiator && !seenSysIds[currentInitiator]) {
                rfiTargetsForThisRequest.unshift({
                    sys_id: currentInitiator,
                    label: 'Initiator',
                    name: initiatorName
                });
            }

            var openRfiForThisRequest = null;
            var rfiCheckGr = new GlideRecord('x_birl3_clm_clm_rfi');
            rfiCheckGr.addQuery('u_request', gr.sys_id);
            rfiCheckGr.addQuery('u_status', 'open');
            rfiCheckGr.addQuery('u_raised_by', currentUser); // ONLY block/show banner for the RFI raiser
            rfiCheckGr.query();
            if (rfiCheckGr.next()) {
                openRfiForThisRequest = {
                    target_role: rfiCheckGr.getValue('u_target_role'),
                    target_name: rfiCheckGr.getDisplayValue('u_target_user') + '',
                    question:    rfiCheckGr.getValue('u_question'),
                    raised_on:   rfiCheckGr.getDisplayValue('sys_created_on')
                };
            }

            results.push({
                sys_id:                  gr.sys_id + '',
                number:                  gr.number + '',
                customer_name:           custName,
                customer_code:           custCode,
                customer_type:           gr.customer_type + '',
                segment:                 gr.segment + '',
                requested_limit:         parseFloat(gr.requested_limit)    / 100000,
                active_sd:               parseFloat(gr.active_sd)          / 100000,
                net_exposure:            parseFloat(gr.net_exposure)        / 100000,
                max_allowable:           parseFloat(gr.max_allowable_limit) / 100000,
                system_mult:             gr.system_multiplier + '',
                implied_mult:            parseFloat(gr.implied_multiplier)  || 0,
                is_deviation:            (gr.is_deviation == true || gr.is_deviation == 'true'),
                nod:                     parseFloat(gr.nod_days)            || 0,
                pan_level_sd:            panLevelSD / 100000,
                aging_rating:            gr.aging_rating + '',
                aging_detail:            agingDetail,
                aging_table:             agingTable,
                vintage_days:            parseInt(gr.customer_vintage_days) || 0,
                cheque_bounces:          parseInt(gr.cheque_bounces_12m)    || 0,
                market_perception:       gr.market_perception + '',
                justification:           gr.business_justification + '',
                deviation_justification: gr.deviation_justification + '',
                review_date:             reviewDateStr,
                initiator:               initiatorName,
                panlevelcl:              gr.pan_level_cl + '',
                current_credit_limit:    gr.current_credit_limit + '',
                code_level_current_limit: codeLevelCurrent,
                code_level_total_requested: codeLevelTotal,
                code_level_requested_additional: codeLevelRequestedAdditional,
                code_level_total_requested_l: codeLevelTotal / 100000,

                // ── NEW: fields for the redesigned Limit tables ──────────
                code_level_sd:           grNum(gr, 'u_code_level_sd'),
                code_level_os:           grNum(gr, 'outstanding_amount'),
                pan_level_os:            grNum(gr, 'u_pan_level_os'),
                pan_sd_abs:              grNum(gr, 'pan_level_sd'),
                pan_cl_abs:              grNum(gr, 'pan_level_cl'),
                requested_limit_abs:     grNum(gr, 'requested_limit'),
                current_limit_expiry:    reviewDateStr,
                segment_breakdown: {
                    Cement: { cl: grNum(gr, 'u_cement_cl'), sd: grNum(gr, 'u_cement_sd') },
                    BPD:    { cl: grNum(gr, 'u_bpd_cl'),    sd: grNum(gr, 'u_bpd_sd')    },
                    RMC:    { cl: grNum(gr, 'u_rmc_cl'),    sd: grNum(gr, 'u_rmc_sd')    }
                },
                // ─────────────────────────────────────────────────────────

                approver_role:           gr.required_approver_level + '',
                approval_steps:          approvalStepsForThisRequest,
                rfi_targets:             rfiTargetsForThisRequest,
                open_rfi:                openRfiForThisRequest,
                answered_rfis:           answeredRfisForThisRequest,
                approval_history:        sequence,
                previous_approval:       previousApproval,
                pan:                     custPAN,
                depot:                   custDepot,
                depot_name:              custDepotName,
                zone:                    custZone,
                zone_name:               custZoneName,
                region:                  custRegion,
                region_name:             custRegionName,
                approval_comments:       approvalComments,
                attachments:             attachments,
                is_resubmitted:          (gr.u_resubmission_count > 0),
                resubmission_count:      parseInt(gr.u_resubmission_count) || 0,
                override_limit:          previousApproval ? (previousApproval.amount / 100000) : null,
                created:                 gr.sys_created_on.getDisplayValue(),

                // TOOL WORKING FIELDS (TRADE)
                tool_p1:                 parsedP1,
                tool_p2:                 parseFloat(gr.getValue('u_tool_p2')) || null,
                tool_p3:                 parseFloat(gr.getValue('u_tool_p3')) || null,
                tool_safe_limit:         parseFloat(gr.getValue('u_tool_safe_limit')) || null,
                tool_mpq:                parseFloat(gr.getValue('u_tool_mpq')) || 0,
                tool_order_rate:         parseFloat(gr.getValue('u_tool_order_rate')) || 0,
                tool_expected_potential: parseFloat(gr.getValue('u_tool_expected_potential')) || 0,
                tool_current_sob:        parseFloat(gr.getValue('u_tool_current_sob')) || 0,
                tool_expected_sob:       parseFloat(gr.getValue('u_tool_expected_sob')) || 0,
                tool_internal_rating:    gr.getValue('u_tool_internal_rating') || '',
                tool_external_rating:    gr.getValue('u_tool_external_rating') || '',
                tool_document_type:      gr.getValue('u_tool_document_type') || '',
                tool_matrix_list:        toolMatrixList
            });
        }

        return results;
    }

    // ── Helper: sync THIS USER's approval to sysapproval_approver ──────
    function syncFlowApproval(requestSysId, decision, comments) {
        try {
            var apGr = new GlideRecord('sysapproval_approver');
            apGr.addQuery('source_table', 'x_birl3_clm_clm_new_credit_request');
            apGr.addQuery('document_id', requestSysId);
            apGr.addQuery('approver', gs.getUserID()); // THIS USER ONLY
            apGr.addQuery('state', 'requested');
            apGr.query();

            var synced = 0;
            while (apGr.next()) {
                if (decision === 'approve') {
                    apGr.state    = 'approved';
                    apGr.comments = comments || 'Approved via CLM Dashboard';
                } else if (decision === 'reject') {
                    apGr.state    = 'rejected';
                    apGr.comments = comments || 'Rejected via CLM Dashboard';
                } else if (decision === 'return') {
                    apGr.state = 'cancelled';
                    apGr.comments = 'Returned to initiator: ' + (comments || '');
                }
                apGr.update();
                synced++;
                gs.info('CLM Dashboard: synced sysapproval ' + apGr.sys_id + ' → ' + apGr.state);
            }

            if (synced === 0) {
                gs.info('CLM Dashboard: no pending sysapproval_approver found for ' + requestSysId + ' user ' + gs.getUserID());
            }
        } catch(e) {
            gs.error('CLM Dashboard: syncFlowApproval error: ' + e.message);
        }
    }

    // ── REFRESH ─────────────────────────────────────────────────────────
    if (action === 'refresh') {
        data.requests = loadRequests();
        return;
    }

    // ── DECIDE ──────────────────────────────────────────────────────────
    if (action === 'decide') {

        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!gr.get(input.sys_id)) {
            data.success = false;
            data.error   = 'Request not found.';
            return;
        }
        var requestNum = gr.number + '';
        var custName   = gr.customer.getDisplayValue();
        var comments   = input.comments || '';

        var originalInitiator = gr.initiator + '';

        if (input.decision === 'approve') {

            var sequence = [];
            try {
                sequence = JSON.parse(gr.u_approver_sequence + '');
            } catch(e) { sequence = []; }

            var currentOrder   = parseInt(gr.u_current_approver_order) || 1;
            var totalApprovers = sequence.length;

            // ── Resolve the approved figure ──
            // For Trade, SD/credit limit is siloed at the CODE level, so the
            // decision surface is u_code_level_total_requested — not the
            // PAN-level requested_limit (which exists only for routing/
            // net-exposure/multiplier checks). Non-Trade/Key keep the old
            // PAN-level behavior.
            var approvedLimit = 0;
            if (input.approved_limit) {
                approvedLimit = parseFloat(
                    input.approved_limit.toString().replace(/,/g, '')
                ) || 0;
            }

            var isTradeReq        = (gr.customer_type + '') === 'Trade';
            var codeLevelTotalReq = parseFloat(gr.getValue('u_code_level_total_requested')) || 0;
            var finalCodeLimit    = approvedLimit > 0 ? approvedLimit : codeLevelTotalReq;
            var finalPanLimit     = approvedLimit > 0 ? approvedLimit : (parseFloat(gr.approved_limit) || parseFloat(gr.requested_limit));

            if (isTradeReq) {
                gr.setValue('u_approved_code_limit', finalCodeLimit);
                gr.approved_limit = finalCodeLimit; // kept in sync — both now mean "code-level" for Trade
            } else {
                gr.approved_limit = finalPanLimit;
            }

            for (var s = 0; s < sequence.length; s++) {
                if (sequence[s].order === currentOrder) {
                    sequence[s].status           = 'approved';
                    sequence[s].approved_by      = gs.getUserID();
                    sequence[s].approved_by_name = gs.getUserDisplayName();
                    sequence[s].approved_on      = new GlideDateTime().toString();
                    sequence[s].approved_limit   = isTradeReq ? finalCodeLimit : finalPanLimit;
                    sequence[s].approver_role    = sequence[s].role || '';
                }
            }
            gr.u_approver_sequence = JSON.stringify(sequence);

            if (currentOrder >= totalApprovers) {

                // ── FINAL APPROVER ──
                gr.setValue('approver', gs.getUserID());
                gr.initiator = originalInitiator;

                gr.setWorkflow(false);
                gr.autoSysFields(false);
                gr.update();
                syncFlowApproval(input.sys_id, 'approve', comments);

                data.success          = true;
                data.processed_sys_id = input.sys_id;
                data.is_final         = true;
                data.message          = requestNum + ' fully approved for ' + custName;

            } else {

                // ── INTERMEDIATE APPROVER ──
                gr.u_current_approver_order = currentOrder + 1;
                gr.initiator = originalInitiator;
                gr.setWorkflow(false);
                gr.autoSysFields(false);
                gr.update();

                syncFlowApproval(input.sys_id, 'approve', comments);

                var nextApproverName = '';
                for (var n = 0; n < sequence.length; n++) {
                    if (sequence[n].order === currentOrder + 1) {
                        var nGr = new GlideRecord('sys_user');
                        if (nGr.get(sequence[n].user_sys_id)) {
                            nextApproverName = nGr.name + '';
                        }
                    }
                }

                data.success          = true;
                data.processed_sys_id = input.sys_id;
                data.is_final         = false;
                data.message          = requestNum + ' approved at level ' + currentOrder
                    + '. Forwarded to: ' + (nextApproverName || 'next approver') + '.';
            }

        } else if (input.decision === 'reject') {

            gr.state            = 'Rejected';
            gr.rejection_reason = comments;

            gr.comments         = "Rejected via Approver Dashboard\nReason: " + comments;

            gr.setValue('approver', gs.getUserID());
            gr.initiator = originalInitiator;
            gr.setWorkflow(false);
            gr.autoSysFields(false);
            gr.update();

            syncFlowApproval(input.sys_id, 'reject', comments);

            var rejectFlowGr = new GlideRecord('sys_flow_context');
            rejectFlowGr.addQuery('source_record', input.sys_id);
            rejectFlowGr.addQuery('state', 'IN', 'WAITING,IN_PROGRESS');
            rejectFlowGr.query();

            while (rejectFlowGr.next()) {
                sn_fd.FlowAPI.cancel(rejectFlowGr.getUniqueValue(), 'Terminated: Request rejected via dashboard.');
            }

            var rejInitGr = new GlideRecord('sys_user');
            if (rejInitGr.get(originalInitiator)) {
                var rejEmail = rejInitGr.email + '';
                if (rejEmail) {
                    gs.eventQueue(
                        'x_birl3_clm.request_rejected',
                        gr,
                        rejEmail,
                        comments
                    );
                    gs.info('CLM: fired request_rejected event for ' + rejEmail);
                }
            }
            data.success          = true;
            data.processed_sys_id = input.sys_id;
            data.message          = requestNum + ' rejected.';
        }

        return;
    }

    // ── SEND RFI ─────────────────────────────────────────────────────────
    if (action === 'send_rfi') {
        var rfiMgr = new CLMRfiManager();
        var rfiResult = rfiMgr.createRfi({
            request_sys_id:   input.sys_id,
            raised_by_sys_id: gs.getUserID(),
            raised_by_role:   input.raised_by_role || '',
            target_sys_id:    input.target_sys_id,
            target_role:      input.target_role || '',
            question:         input.question || ''
        });

        data.success = rfiResult.success;
        data.error   = rfiResult.error;
        if (rfiResult.success) {
            data.message = 'Request for information sent to ' + (input.target_role || 'selected approver') + '.';
        }
        return;
    }

    // ── DEFAULT LOAD ─────────────────────────────────────────────────────
    data.requests = loadRequests();

})();
